 jsonb_build_array('تسطیح منابع صرف بر مبنای در دسترس بودن نیرو کافی نیست','ریسک چگالی پرسنل بیش از ظرفیت ایمن یک منطقه محدود','هماهنگی با HSE برای تعیین حداقل/حداکثر ظرفیت ایمن هر منطقه','لحاظ این محدودیت در الگوریتم تسطیح منابع برنامه'),
