 jsonb_build_array('مقایسه مدت پیشنهادی با داده تاریخی و بهره‌وری واقعی مشابه','عدم پذیرش صرف ادعای خوش‌بینانه تیم اجرایی بدون بررسی','لحاظ ریسک مغایرت در تحلیل احتمالاتی برنامه','هدف نهایی: برنامه واقع‌بینانه‌تر برای تصمیم‌گیری مدیریتی'),
